\label{lem:unique}
    Suppose ${\mathcal A}$ is Krull--Schmidt and $X,Y \in {\mathcal A}$.
    Then $\mathsf{add} X \cap \mathsf{add} Y \neq 0$ if and only if $X$ and $Y$ share an (indecomposable) direct summand.

\label{lem:radical}
    Suppose $\mathcal{A}$ is Krull--Schmidt.
    For $X,Y \in \mathcal{A}$ indecomposable any morphism $f \in {\mathcal A}(X, Y)$ is either in $\mathsf{rad}_{\mathcal A}(X,Y)$ or an isomorphism.
    For $X,Y \in {\mathcal A}$ not necessarily indecomposable the three statements
    \begin{align*}
        &\mathsf{rad}_{{\mathcal A}}(X, Y) = {\mathcal A}(X, Y) \text{,}\\
        &\mathsf{rad}_{{\mathcal A}}(Y, X) = {\mathcal A}(Y, X) \text{,}\\
        &\mathsf{add} (X) \cap \mathsf{add} (Y) =0 
    \end{align*}
    are equivalent.

\begin{align*}
        &\mathsf{rad}_{{\mathcal A}}(X, Y) = {\mathcal A}(X, Y) \text{,}\\
        &\mathsf{rad}_{{\mathcal A}}(Y, X) = {\mathcal A}(Y, X) \text{,}\\
        &\mathsf{add} (X) \cap \mathsf{add} (Y) =0 
    \end{align*}

\label{lem:wellknownrad}
    Let $\Phi \colon {\mathcal A} \to {\mathcal B}$ be a full $\Bbbk$-linear functor.
    Then $\Phi(\mathsf{rad}_{{\mathcal A}}(X,Y))$ is a subset of $\mathsf{rad}_{{\mathcal B}}(\Phi(X),\Phi(Y))$ for any $X, Y \in {\mathcal A}$.

\label{lem:localepi}
   Let $\phi \colon \Lambda \to \Lambda/I$ be the quotient of a local $\Bbbk$-algebra $\Lambda$ by an ideal $I \unlhd \Lambda$.
   Then $\phi(\mathsf{rad} \Lambda) = \mathsf{rad} \Lambda/I$ and if $I \lhd \Lambda$ is proper then $\Lambda/I$ is local.

\label{lem:radicalfunctor}
    Suppose $\Phi \colon {\mathcal A} \to {\mathcal B}$ is a full, essentially surjective $\Bbbk$-linear functor and that ${\mathcal A}$ is a Krull--Schmidt category.
    Then
    \begin{enumerate}[label={(\alph*)}]
        \item ${\mathcal B}$ is a Krull--Schmidt category,\label{item:ks}
        \item every $X \in {\mathcal A}$ admits a decomposition $X \cong X_1 \oplus \cdots \oplus X_n$ and such that for each $1 \leq i \leq n$ either $X_i \in \Phi^{-1}(\opname{ind} {\mathcal B}) \cap \opname{ind} {\mathcal A}$ or $X_{i} \in \Phi^{-1}(0) \cap \opname{ind} {\mathcal A}$, and\label{item:kspreimage}

        \item $\Phi(\mathsf{rad}^n_{{\mathcal A}}(X,Y)) = \mathsf{rad}^n_{{\mathcal B}}(\Phi(X), \Phi(Y))$ for $n \geq 1$ and $X,Y \in \mathcal{A}$.\label{item:radicaliso}
    \end{enumerate}
    In particular, the essential image of $\Phi^{-1}(\opname{ind} {\mathcal B}) \cap \opname{ind} {\mathcal A}$ under $\Phi$ is $\opname{ind} {\mathcal B}$.

\label{rem:krause}
Because ${\mathcal A}$ is Krull-Schmidt it follows from \cite[Corollary 1.4]{KS98} that every morphism in any additive, idempotent complete subcategory ${\mathcal B}$ of ${\mathcal A}$ admits a right minimal version. 
In particular, any object in ${\mathcal A}$ that admits a right almost split morphism also admits a sink morphism and any object in ${\mathcal A}$ that admits a right ${\mathcal B}$-approximation admits a right minimal right ${\mathcal B}$-approximation.

\label{lem:sinksubcat}
    Suppose ${\mathcal B} \subseteq {\mathcal A}$ is an additive, idempotent complete and covariantly finite subcategory and let $X \in {\mathcal B}$.
    If $X$ admits a sink morphism in ${\mathcal A}$ then it admits a sink morphism in ${\mathcal B}$.

\label{lem:sinkiscover}
    Suppose the quiver of ${\mathcal A}$ has no loops at an object $X \in \opname{ind} {\mathcal A}$.
    Then a morphism $f \colon Y \to X$ is a sink morphism for $X$ if and only if it is a right minimal right $({\mathcal A} \setminus \mathsf{add} X)$-approximation of $X$.

\label{lem:sinkcover}
   Suppose that $X \in \opname{ind} \mathcal{A}$ admits a sink morphism.
   Then ${\mathcal A} \setminus \mathsf{add} X$ is covariantly finite in ${\mathcal A}$.

